const raw = response.choices?.[0]?.message?.content || response.message?.content || response.content || '';
function arr(v) { return Array.isArray(v) ? v : (v == null || v === '' ? [] : [v]); }
function parse(text) {
  const clean = String(text || '').trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  try { return JSON.parse(clean); } catch (e) {}
  const start = clean.indexOf('{'); const end = clean.lastIndexOf('}');
  if (start >= 0 && end > start) return JSON.parse(clean.slice(start, end + 1));
  throw new Error('Model did not return parseable JSON');
}
function buildTestVariants() {
  const recipeTitle = (type, fallback) => (source.recipes || []).find(r => r.recipe_type === type)?.title || fallback;
  const reelGroups = [
    ['close', 'close_to_competitor', recipeTitle('close_to_competitor', 'source pattern')],
    ['viral', 'more_viral', recipeTitle('more_viral', 'viral proof pattern')],
    ['premium', 'more_premium', recipeTitle('more_premium', 'premium detail pattern')]
  ];
  const reels = [];
  for (const [group, recipeType, title] of reelGroups) {
    for (let i = 1; i <= 4; i++) {
      reels.push({
        group,
        number: i,
        first_frame: `TEST ${group} ${i}: макро-деталь стола + сильный текст первого кадра`,
        hook_text: `Тестовый хук ${i}: стол выглядит дороже из-за одной детали`,
        screen_text_json: [`${title}`, 'деталь -> процесс -> reveal', 'напишите размер'],
        scene_plan_json: [
          { t: '0-2', shot: 'макро текстуры/кромки/стыка', purpose: 'стоп-скролл' },
          { t: '2-7', shot: 'быстрые кадры процесса руками без лиц', purpose: 'доказательство' },
          { t: '7-12', shot: 'финальный reveal стола в интерьере', purpose: 'желание и CTA' }
        ],
        caption: `Тестовое описание для ${group}: покажите размер, материал и одну премиальную деталь. Первый абзац должен удерживать внимание.`,
        cta: 'Напишите размер в ДМ - подберем вариант стола под интерьер.',
        viral_mechanism: 'контрастный первый кадр + proof + reveal',
        source_pattern_preserved_json: ['макро', 'процесс руками', 'финальный reveal'],
        uniqueness_moves_json: ['другие слова', 'другой ракурс', 'ваш товар'],
        borrowed_elements_json: ['механика первого кадра', 'темп монтажа'],
        changed_elements_json: ['брендинг', 'текст', 'конкретный стол'],
        forbidden_checks_json: ['без чужого логотипа', 'без лиц как ключевого элемента'],
        render_notes: 'Тестовый fallback без AI-video: собрать через монтаж/оверлеи.',
        ai_video_prompt: ''
      });
    }
  }
  const stories = [1,2,3,4].map(i => ({
    number: i,
    first_frame: `TEST story ${i}: вопрос по выбору стола`,
    hook_text: 'Какой стол смотрится дороже?',
    screen_text_json: ['выберите вариант', 'материал / размер / покрытие'],
    scene_plan_json: [{ t: '0-5', shot: 'опрос + 2 варианта покрытия' }],
    caption: 'Тестовая сторис для проверки доставки.',
    cta: 'Ответьте в сторис или напишите размер в ДМ.',
    viral_mechanism: 'интерактивный выбор',
    borrowed_elements_json: ['визуальная механика'],
    changed_elements_json: ['текст и товар'],
    forbidden_checks_json: ['без чужого бренда']
  }));
  const captions = ['close','viral','premium'].map(group => ({ group, caption: `Тестовое описание ${group}: первый абзац цепляет, дальше материал/размер/CTA.`, cta: 'Напишите размер в ДМ.', hook_text: 'Этот стол меняет ощущение комнаты.' }));
  return { reels, stories, captions };
}
let parsed;
if (response.error) {
  if (!source.test_mode) return [{ json: { ok: false, error: response.error.message || 'Polza request failed', raw_model_response: JSON.stringify(response.error).slice(0, 2500) } }];
  parsed = buildTestVariants();
} else {
  try { parsed = parse(raw || JSON.stringify(response)); } catch (error) {
    if (!source.test_mode) return [{ json: { ok: false, error: error.message, raw_model_response: String(raw).slice(0, 2500) } }];
    parsed = buildTestVariants();
  }
}
const recipeByGroup = new Map();
for (const r of source.recipes || []) {
  if (r.recipe_type === 'close_to_competitor') recipeByGroup.set('close', r.id);
  if (r.recipe_type === 'more_viral') recipeByGroup.set('viral', r.id);
  if (r.recipe_type === 'more_premium') recipeByGroup.set('premium', r.id);
  if (r.recipe_type === 'story') recipeByGroup.set('story', r.id);
}
const now = new Date().toISOString();
const rows = [];
function base(v, group, format, n) {
  return {
    batch_id: source.batch_id,
    pattern_recipe_id: recipeByGroup.get(group) || null,
    content_pattern_id: source.pattern_id,
    source_competitor_video_id: source.competitor_video_id,
    variant_group: group,
    variant_number: Number(n) || null,
    format,
    first_frame: String(v.first_frame || ''),
    hook_text: String(v.hook_text || ''),
    screen_text_json: arr(v.screen_text_json),
    scene_plan_json: arr(v.scene_plan_json),
    caption: String(v.caption || ''),
    cta: String(v.cta || ''),
    source_refs_json: [{ content_pattern_id: source.pattern_id, competitor_video_id: source.competitor_video_id }],
    borrowed_elements_json: arr(v.borrowed_elements_json),
    changed_elements_json: arr(v.changed_elements_json),
    forbidden_checks_json: arr(v.forbidden_checks_json),
    generation_model: 'openai/gpt-5.2',
    status: 'idea_created',
    created_at: now,
    updated_at: now
  };
}
for (const [idx, v] of arr(parsed.reels).entries()) {
  const g = ['close', 'viral', 'premium'].includes(v.group) ? v.group : (idx < 4 ? 'close' : idx < 8 ? 'viral' : 'premium');
  rows.push(base(v, g, 'reel', v.number || ((idx % 4) + 1)));
}
for (const [idx, v] of arr(parsed.stories).entries()) rows.push(base(v, 'story', 'story', v.number || idx + 1));
for (const [idx, v] of arr(parsed.captions).entries()) {
  const g = ['close', 'viral', 'premium'].includes(v.group) ? v.group : ['close', 'viral', 'premium'][idx % 3];
  rows.push(base({ ...v, first_frame: '', screen_text_json: [], scene_plan_json: [], borrowed_elements_json: [], changed_elements_json: [], forbidden_checks_json: [] }, g, 'caption', idx + 1));
}
return [{ json: { ok: rows.length > 0, pattern_id: source.pattern_id, row_count: rows.length, rows, error: rows.length ? undefined : 'No variants generated' } }];

const inserted = $input.first()?.json;
const rows = Array.isArray(inserted) ? inserted : [inserted].filter(Boolean);
return [{ json: { action: 'variants_created', inserted_count: rows.length, message: `WF03 created ${rows.length} content_variants.` } }];

